                                                        >
                                                            <Loader2 size={16} /> Aguarda Processamento
                                                        </button>
                                                    )}
                                                </div>
                                            </div>
                                        );
                                    })
                                }
                            </div>
                        )}
                    </div>
                )}

                {/* PEOPLE */}
                {currentView === 'people' && (
                    <div className="max-w-4xl mx-auto space-y-8 pb-20">
