                                      {detectedPeopleData.length > 0 && (
                                          <div className="mt-2 ml-2 bg-white dark:bg-slate-900 border border-green-200 dark:border-green-900/50 p-3 rounded-xl shadow-lg animate-in fade-in slide-in-from-top-2 max-w-sm">
