                                                         <button onClick={() => updateReport(activeReport.id, activeReport.generalConclusion, activeReport.results)} className="px-3 py-1.5 bg-green-600 hover:bg-green-500 rounded text-xs text-white flex items-center gap-1"><Check size={14}/> Guardar Edição</button>
                                                     )}
                                                 </div>
                                            </div>
                                            <div className="flex-1 overflow-y-auto p-8 space-y-8 bg-gray-50 dark:bg-slate-950">
                                                 <div className="bg-white dark:bg-slate-900 p-6 rounded-xl border border-gray-200 dark:border-slate-800 shadow-sm">
                                                     <h3 className="text-primary-600 dark:text-primary-400 font-bold mb-2 uppercase text-xs">Conclusão Geral</h3>
                                                     {editingReportId === activeReport.id ? (
                                                         <textarea className="w-full h-32 bg-gray-50 dark:bg-slate-950 border border-gray-300 dark:border-slate-700 rounded p-2 text-gray-800 dark:text-slate-300 text-sm" value={activeReport.generalConclusion} onChange={(e) => { const updated = { ...activeReport, generalConclusion: e.target.value }; setProject(prev => ({ ...prev, savedReports: prev.savedReports.map(r => r.id === updated.id ? updated : r) })); }} />
                                                     ) : (
                                                         <p className="text-gray-700 dark:text-slate-300 leading-relaxed text-sm">{activeReport.generalConclusion}</p>
                                                     )}
                                                 </div>
                                                 <div className="space-y-6">
                                                      {activeReport.results.map((res, idx) => (
                                                          <div key={idx} className="border border-gray-200 dark:border-slate-800 rounded-xl overflow-hidden bg-white dark:bg-slate-900 shadow-sm">
                                                              <div className="bg-gray-50 dark:bg-slate-800/50 p-4 flex justify-between items-center border-b border-gray-100 dark:border-slate-800">
                                                                  <h4 className="font-bold text-gray-800 dark:text-slate-200 text-sm">{res.factText}</h4>
                                                                  {editingReportId === activeReport.id ? (
                                                                      <select value={res.status} onChange={(e) => { const newResults = [...activeReport.results]; newResults[idx] = { ...res, status: e.target.value as any }; setProject(prev => ({ ...prev, savedReports: prev.savedReports.map(r => r.id === activeReport.id ? { ...r, results: newResults } : r) })); }} className="bg-white dark:bg-slate-900 text-xs text-gray-900 dark:text-white border border-gray-300 dark:border-slate-700 rounded p-1">
                                                                          <option value="Confirmado">Confirmado</option><option value="Desmentido">Desmentido</option><option value="Inconclusivo/Contraditório">Inconclusivo</option><option value="Não Mencionado">Não Mencionado</option>
                                                                      </select>
                                                                  ) : (
                                                                      <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase ${res.status === 'Confirmado' ? 'bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-400' : res.status === 'Desmentido' ? 'bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-400' : 'bg-gray-100 text-gray-500 dark:bg-slate-700 dark:text-slate-400'}`}>{res.status}</span>
                                                                  )}
                                                              </div>
                                                              <div className="p-6">
                                                                  {editingReportId === activeReport.id ? (
                                                                      <textarea className="w-full h-24 bg-gray-50 dark:bg-slate-950 border border-gray-300 dark:border-slate-700 rounded p-2 text-gray-800 dark:text-slate-300 text-sm mb-4" value={res.summary} onChange={(e) => { const newResults = [...activeReport.results]; newResults[idx] = { ...res, summary: e.target.value }; setProject(prev => ({ ...prev, savedReports: prev.savedReports.map(r => r.id === activeReport.id ? { ...r, results: newResults } : r) })); }} />
                                                                  ) : (
                                                                      <p className="text-gray-600 dark:text-slate-400 text-sm mb-6 border-l-2 border-gray-300 dark:border-slate-700 pl-4">{res.summary}</p>
                                                                  )}

                                                                  {res.citations.length > 0 && (
                                                                    <div className="space-y-3 pt-4 border-t border-gray-100 dark:border-slate-800/50">
                                                                        <h5 className="text-[10px] uppercase font-bold text-gray-400 dark:text-slate-500 mb-2">Citações e Fontes:</h5>
                                                                        {(() => {
                                                                            // GROUP CITATIONS BY FILE FOR REPORT
                                                                            const groupedByFile: Record<string, Citation[]> = {};
                                                                            res.citations.forEach(c => {
                                                                                if(!groupedByFile[c.fileId]) groupedByFile[c.fileId] = [];
                                                                                groupedByFile[c.fileId].push(c);
                                                                            });

                                                                            return Object.entries(groupedByFile).map(([fileId, cits]) => {
                                                                                 const fileName = cits[0].fileName;
                                                                                 const contentLines = cits.map(c => `* "${c.text}" [${c.timestamp}]`);

                                                                                 return (
                                                                                    <CitationGroup 
                                                                                        key={fileId}
                                                                                        fileName={fileName}
                                                                                        contentLines={contentLines}
                                                                                        evidenceFiles={evidenceFiles}
                                                                                        onSeek={(fid, sec) => { setActiveEvidenceId(fid); setSeekSeconds(sec); }}
                                                                                        onOpenOriginal={handleOpenOriginal}
                                                                                        renderInline={renderTextWithInlineCitations}
                                                                                    />
                                                                                 );
                                                                            });
                                                                        })()}
                                                                    </div>
                                                                  )}
                                                              </div>
                                                          </div>
                                                      ))}
                                                 </div>
                                            </div>
                                        </>
                                    );
                                })()
                           ) : (
                               <div className="flex items-center justify-center h-full text-gray-400 dark:text-slate-500">Selecione um relatório.</div>
                           )}
                      </div>
                  </div>
                )}
            </div>
        </main>

        {/* MANUAL IMPORT MODAL */}
        {isManualImportOpen && (
            <div className="fixed inset-0 z-50 bg-black/80 flex items-center justify-center p-4">
                <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl w-full max-w-2xl border border-gray-200 dark:border-slate-800 shadow-2xl">
                    <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-4">Importar Texto Manualmente</h3>
                    <input className="w-full bg-gray-50 dark:bg-slate-950 border border-gray-200 dark:border-slate-800 p-3 rounded-lg text-gray-900 dark:text-white mb-4" placeholder="Nome do Documento / Depoimento" value={manualName} onChange={e => setManualName(e.target.value)} />
                    <textarea 
                        className="w-full h-64 bg-gray-50 dark:bg-slate-950 border border-gray-200 dark:border-slate-800 rounded-lg p-3 text-sm text-gray-800 dark:text-slate-300 outline-none focus:border-primary-500 resize-none"
                        placeholder="Cole o texto aqui..."
                        value={manualText}
                        onChange={e => setManualText(e.target.value)}
                    />
                    <div className="flex justify-end gap-2 mt-4">
                        <button onClick={() => setIsManualImportOpen(false)} className="px-4 py-2 text-gray-500 hover:text-gray-700 dark:text-slate-400 dark:hover:text-slate-200 text-sm font-bold">Cancelar</button>
                        <button onClick={handleManualImport} className="px-4 py-2 bg-primary-600 hover:bg-primary-500 text-white rounded-lg text-sm font-bold shadow-lg shadow-primary-900/20">Importar</button>
                    </div>
                </div>
            </div>
        )}

        {/* EVIDENCE VIEWER MODAL */}
        {activeEvidenceId && (
            <EvidenceViewer 
                file={evidenceFiles.find(f => f.id === activeEvidenceId) || null}
                processedData={project.processedData.find(pd => pd.fileId === activeEvidenceId)}
                initialSeekSeconds={seekSeconds}
                personName={evidenceFiles.find(f => f.id === activeEvidenceId)?.personId ? project.people.find(p => p.id === evidenceFiles.find(f => f.id === activeEvidenceId)?.personId)?.name : undefined}
                onClose={() => { setActiveEvidenceId(null); setSeekSeconds(null); }}
                onRenameSpeaker={handleRenameSpeaker}
            />
        )}

        {/* EXPORT MODAL */}
        {exportModal.isOpen && (
            <div className="fixed inset-0 z-50 bg-black/80 flex items-center justify-center p-4">
                <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl w-full max-w-md border border-gray-200 dark:border-slate-800 shadow-2xl">
                    <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-2">Exportar Conversa</h3>
                    <p className="text-sm text-gray-500 dark:text-slate-400 mb-4">Escolha o formato de exportação.</p>
                    <div className="flex flex-col gap-2">
                        {exportModal.messageId && (
                            <button onClick={() => handleExportChat('SINGLE')} className="p-3 bg-blue-50 dark:bg-primary-900/20 text-blue-700 dark:text-primary-300 rounded-lg text-sm font-bold hover:bg-blue-100 dark:hover:bg-primary-900/40 text-left transition-colors">
                                Exportar Apenas Esta Resposta
                            </button>
                        )}
                        <button onClick={() => handleExportChat('FULL')} className="p-3 bg-gray-50 dark:bg-slate-800 text-gray-700 dark:text-slate-300 rounded-lg text-sm font-bold hover:bg-gray-100 dark:hover:bg-slate-700 text-left transition-colors">
                            Exportar Toda a Conversa
                        </button>
                    </div>
                    <button onClick={() => setExportModal({ isOpen: false })} className="w-full mt-4 py-2 text-gray-400 hover:text-gray-600 dark:hover:text-slate-300 text-sm font-bold">Cancelar</button>
                </div>
            </div>
        )}

        {/* QUOTA MODAL */}
        {showQuotaModal && (
            <div className="fixed inset-0 z-[60] bg-black/90 flex items-center justify-center p-4 animate-in fade-in duration-200">
                 <div className="bg-white dark:bg-slate-900 p-8 rounded-2xl max-w-sm text-center border border-red-200 dark:border-red-900/50 shadow-2xl">
                     <div className="w-16 h-16 bg-red-100 dark:bg-red-900/30 rounded-full flex items-center justify-center mx-auto mb-4 text-red-500 dark:text-red-400">
                        <AlertTriangle size={32} />
                     </div>
                     <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-2">Limite de Quota Atingido</h3>
                     <p className="text-sm text-gray-600 dark:text-slate-300 mb-6 leading-relaxed">
                         A API do Google Gemini atingiu o limite de pedidos gratuitos. 
                         <br/><br/>
                         Por favor, aguarde <strong>alguns instantes</strong> antes de tentar novamente.
                     </p>
                     <button onClick={() => setShowQuotaModal(false)} className="w-full py-2.5 bg-red-600 hover:bg-red-500 text-white rounded-xl font-bold shadow-lg shadow-red-900/20 transition-transform active:scale-95">
                         Entendido
                     </button>
                 </div>
            </div>
        )}

    </div>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";
import { EvidenceFile, EvidenceType, Fact, FactAnalysis, FactStatus, AnalysisReport, ChatMessage, ProcessedContent, Citation } from "../types";

/**
 * Converts a File object to a Base64 string for the API.
 */
const fileToGenerativePart = async (file: File): Promise<{ inlineData: { data: string; mimeType: string } }> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const result = reader.result as string;
      const base64String = result.includes(',') ? result.split(',')[1] : result;
      resolve({
        inlineData: {
          data: base64String,
          mimeType: file.type,
        },
      });
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

/**
 * Cleans repetitive word loops (Stuttering Hallucinations).
 */
export const cleanRepetitiveLoops = (text: string): string => {
    if (!text) return "";
    const loopRegex = /\b(\w+)(?:[\s,.]+\1\b){3,}/gi;
    let cleaned = text.replace(loopRegex, '$1');
    const phraseLoopRegex = /(.{5,50}?)(?:[\s,.]+\1){3,}/gi;
    cleaned = cleaned.replace(phraseLoopRegex, '$1');
    return cleaned;
};

/**
 * Sanitizes the raw transcription text to remove AI hallucinations, loops, and time-travel artifacts.
 */
export const sanitizeTranscript = (rawText: string): { timestamp: string; seconds: number; text: string }[] => {
    const segments: { timestamp: string; seconds: number; text: string }[] = [];

    // STRICT FORMATTING: Ensure NEWLINE before every timestamp to force "one speech per line"
    let formattedText = rawText
        .replace(/([^\n])\s*(\[\d{1,2}:\d{2}(?::\d{2})?\])/g, '$1\n$2')
        .replace(/([^\n])\s+(\d{1,2}:\d{2}:\d{2})/g, '$1\n$2')
        .replace(/([^\n])\s*(\[P[áa]g)/g, '$1\n$2')
        .replace(/(\n\s*){2,}/g, '\n'); 

    const lines = formattedText.split('\n');

    const timestampRegex = /(?:^|[\s\*\-\.\(\[])(?:(?:(\d{1,2}):)?(\d{1,2}):(\d{2})|P[áa]g\.?\s*(\d+)|Page\s*(\d+))(?:\]|\)|:)?[\*\-\)]*\s+(.*)/i;

    let lastSeconds = -1;
    let lastText = "";

    for (const line of lines) {
        if (line.trim().length < 2) continue;

        const match = line.match(timestampRegex);
        if (match) {
            // Time parts
            const hours = match[1] ? parseInt(match[1]) : 0;
            const minutes = match[2] ? parseInt(match[2]) : null;
            const secondsPart = match[3] ? parseInt(match[3]) : null;

            // Page parts
            const pageNum = match[4] || match[5] ? parseInt(match[4] || match[5]) : null;

            let metricValue = 0;
            let displayTimestamp = "";

            if (minutes !== null && secondsPart !== null) {
                metricValue = (hours * 3600) + (minutes * 60) + secondsPart;
                if (hours > 0) {
                     displayTimestamp = `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${secondsPart.toString().padStart(2, '0')}`;
                } else {
                     displayTimestamp = `${minutes.toString().padStart(2, '0')}:${secondsPart.toString().padStart(2, '0')}`;
                }
            } else if (pageNum !== null) {
                metricValue = pageNum; 
                displayTimestamp = `Pág ${pageNum}`;
            }

            let text = match[6] ? match[6].trim() : "";

            // Hallucination check
            if (["subtitles by", "inaudível"].some(t => text.toLowerCase().includes(t))) continue;

            text = cleanRepetitiveLoops(text);

            if (text === lastText) continue;

            if (text && text.length > 0) {
                segments.push({
                    timestamp: displayTimestamp,
                    seconds: metricValue,
                    text: text
                });
                lastSeconds = metricValue;
                lastText = text;
            }

        } else {
            // Append text to previous segment if it looks like continuation
            if (segments.length > 0 && line.trim().length > 0) {
                let cleanLine = cleanRepetitiveLoops(line.trim());
                if (!cleanLine.startsWith('[') && cleanLine.length > 1) {
                    segments[segments.length - 1].text += " " + cleanLine;
                }
            }
        }
    }

    return segments;
};

/**
 * Universal Processing Function: Handles Audio, PDF, and Images.
 */
export const processFile = async (apiKey: string, evidenceFile: EvidenceFile): Promise<ProcessedContent> => {
  if (evidenceFile.isVirtual || !evidenceFile.file) {
      throw new Error("Este ficheiro é virtual e não pode ser processado pela API.");
  }

  const ai = new GoogleGenAI({ apiKey: apiKey });
  const model = "gemini-2.5-flash"; 

  // Determine Prompt based on File Type
  let systemInstruction = "";
  let userPrompt = "";

  if (evidenceFile.type === 'AUDIO') {
      systemInstruction = `
          És um Transcritor Forense Profissional.
          A TUA MISSÃO: Transcrever áudio judicial com rigor absoluto em Português de Portugal.

          REGRAS DE DIARIZAÇÃO (IDENTIFICAÇÃO DE INTERLOCUTORES):
          1. Tenta identificar quem fala pelo contexto (ex: "Senhor Juiz", "Senhora Testemunha").
          2. Se souberes o nome/papel, usa: [MM:SS] **Juiz:** Texto...
          3. Se não souberes, usa identificadores genéricos consistentes: [MM:SS] **Voz 1:** Texto... / [MM:SS] **Voz 2:** Texto...

          REGRAS DE FORMATAÇÃO (RIGOROSAS):
          1. OBRIGATÓRIO: Coloca cada nova fala numa NOVA LINHA.
          2. OBRIGATÓRIO: Inicia cada fala com o carimbo de tempo [MM:SS] ou [HH:MM:SS].
          3. Formato da linha: [Tempo] **Interlocutor:** O que foi dito.

          EXEMPLO DO FORMATO DESEJADO:
          [00:01] **Juiz:** Bom dia a todos.
          [00:03] **Voz 1:** Bom dia, senhor Juiz.
          [01:15:20] **Voz 2:** Não me recordo disso.
      `;
      userPrompt = "Transcreve este áudio. Identifica os interlocutores (Voz 1, Voz 2...) e usa o formato [MM:SS] **Nome:** Texto.";
  } else {
      // PDF / IMAGE / TEXT
      systemInstruction = `
          És um Assistente Legal encarregue de digitalizar Autos de Inquirição e Provas Documentais.
          A TUA MISSÃO: Extrair TODO o texto legível deste documento.
          FORMATO:
          - Se o documento tiver páginas, usa [Pág 1], [Pág 2] em linhas separadas no início de cada página.
          - Divide o texto por parágrafos lógicos.
      `;
      userPrompt = "Extrai o texto integral. Usa [Pág X] para separar páginas.";
  }

  try {
        const filePart = await fileToGenerativePart(evidenceFile.file);

        const response = await ai.models.generateContent({
          model: model,
          contents: {
            parts: [filePart, { text: userPrompt }]
          },
          config: {
            systemInstruction: systemInstruction,
            temperature: 0.2, 
          }
        });

        let rawText = response.text || "";
        if (!rawText.trim()) throw new Error("A IA devolveu uma resposta vazia.");

        // Cleanup
        rawText = rawText.replace(/^```[a-z]*\n/gm, '').replace(/^```/gm, '');

        // Sanitize / Parse
        const segments = sanitizeTranscript(rawText);

        // Fallback for non-timestamped docs
        if (segments.length === 0 && rawText.trim().length > 0) {
            const paragraphs = rawText.split(/\n\s*\n/);
            paragraphs.forEach((p, idx) => {
                if (p.trim()) {
                    segments.push({
                        timestamp: evidenceFile.type === 'AUDIO' ? "00:00" : `Parte ${idx + 1}`,
                        seconds: idx,
                        text: p.trim()
                    });
                }
            });
        }

        const fullText = segments.map(s => `[${s.timestamp}] ${s.text}`).join('\n');

        return {
          fileId: evidenceFile.id,
          fileName: evidenceFile.name,
          fullText: fullText,
          segments: segments,
          processedAt: Date.now()
        };

    } catch (error: any) {
        console.error("Processing Error:", error);
        throw new Error(`Falha no processamento de ${evidenceFile.name}: ${error.message}`);
    }
};

export const parseSecondsSafe = (timestamp: string): number => {
    if (timestamp.includes(':')) {
        const parts = timestamp.split(':').map(Number);
        if (parts.length === 3) {
            return (parts[0] * 3600) + (parts[1] * 60) + parts[2];
        }
        if (parts.length === 2) {
            return (parts[0] * 60) + parts[1];
        }
    }
    const num = timestamp.match(/\d+/);
    return num ? parseInt(num[0]) : 0;
}

/**
 * Analyzes Facts using ALL processed evidence (Audio + Docs).
 */
export const analyzeFactsFromEvidence = async (
  apiKey: string,
  processedData: ProcessedContent[], 
  facts: Fact[],
  peopleMap: Record<string, string>,
  fileMetadata: EvidenceFile[] 
): Promise<AnalysisReport> => {
  if (!processedData.length || !facts.length) {
    throw new Error("São necessários dados e factos.");
  }

  const ai = new GoogleGenAI({ apiKey: apiKey });
  const model = "gemini-2.5-flash";

  const factsList = facts.map((f, i) => `${i + 1}. [ID: ${f.id}] ${f.text}`).join('\n');

  const evidenceContext = processedData.map((t) => {
      const personName = peopleMap[t.fileId] || "Desconhecido";
      const fileData = fileMetadata.find(f => f.id === t.fileId);
      const category = fileData?.category || "OTHER";

      return `
<file name="${t.fileName}" person="${personName}" category="${category}">
${t.fullText}
</file>
`;
  }).join('\n');

  const systemInstruction = `
    És um Juiz e Analista Forense.
    OBJETIVO: Verificar factos cruzando DEPOIMENTOS e DOCUMENTOS.

    FORMATO OBRIGATÓRIO PARA CADA FACTO:
    [[FACT]]
    ID: {id do facto}
    [[STATUS]] {Confirmado | Desmentido | Inconclusivo | Não Mencionado} [[END_STATUS]]
    [[SUMMARY]] Resumo da análise [[END_SUMMARY]]
    [[EVIDENCES]]
    - [NomeDoAudio.mp3 @ 00:00] "Texto citado"
    [[END_EVIDENCES]]
    [[END_FACT]]

    CONCLUSÃO GLOBAL:
    [[CONCLUSION]] Conclusão geral [[END_CONCLUSION]]
  `;

  const prompt = `EVIDÊNCIAS:\n${evidenceContext}\n\nFACTOS:\n${factsList}`;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: { parts: [{ text: prompt }] },
      config: { systemInstruction: systemInstruction, temperature: 0.1 }
    });

    const rawText = response.text || "";
    const results: FactAnalysis[] = [];
    let generalConclusion = "Análise concluída.";

    const conclusionMatch = rawText.match(/\[\[CONCLUSION\]\]([\s\S]*?)\[\[END_CONCLUSION\]\]/);
    if (conclusionMatch) generalConclusion = conclusionMatch[1].trim();

    const factBlocks = rawText.split('[[FACT]]').slice(1);

    for (const block of factBlocks) {
        const idMatch = block.match(/ID:\s*(.*?)(\n|\[)/);
        const factId = idMatch ? idMatch[1].trim() : "";
        const statusMatch = block.match(/\[\[STATUS\]\]([\s\S]*?)\[\[END_STATUS\]\]/);
        const status = statusMatch ? statusMatch[1].trim() as FactStatus : FactStatus.INCONCLUSIVE;
        const summaryMatch = block.match(/\[\[SUMMARY\]\]([\s\S]*?)\[\[END_SUMMARY\]\]/);
        const summaryText = summaryMatch ? summaryMatch[1].trim() : "Sem resumo disponível.";
        const evidencesMatch = block.match(/\[\[EVIDENCES\]\]([\s\S]*?)\[\[END_EVIDENCES\]\]/);
        const evidencesContent = evidencesMatch ? evidencesMatch[1] : "";

        const citations: Citation[] = [];
        const citationRegex = /\[\s*(.*?)\s*@\s*(.*?)\s*\]/g;
        let match;

        while ((match = citationRegex.exec(evidencesContent)) !== null) {
            const fileNameRef = match[1].trim();
            const timestampGroup = match[2].trim();
            const timestamps = timestampGroup.split(',').map(t => t.trim());

            const source = processedData.find(d => 
                d.fileName.toLowerCase().includes(fileNameRef.toLowerCase()) || 
                fileNameRef.toLowerCase().includes(d.fileName.toLowerCase())
            );

            const fileMeta = fileMetadata.find(f => f.id === source?.fileId);
            const isDocument = fileMeta?.category !== 'TESTIMONY';

            if (source) {
                timestamps.forEach(ts => {
                    const seconds = parseSecondsSafe(ts);
                    let text = "Texto indisponível";

                    if (isDocument) {
                         const seg = source.segments.reduce((prev, curr) => {
                             return Math.abs(curr.seconds - seconds) < Math.abs(prev.seconds - seconds) ? curr : prev;
                        }, source.segments[0]);
                        text = seg ? seg.text : text;
                    } else {
                        const centerIdx = source.segments.findIndex(s => Math.abs(s.seconds - seconds) < 2);
                        if (centerIdx !== -1) {
                            const start = Math.max(0, centerIdx - 1);
                            const end = Math.min(source.segments.length, centerIdx + 6);
                            text = source.segments.slice(start, end).map(s => s.text).join(" ");
                        }
                    }

                    citations.push({
                        fileId: source.fileId,
                        fileName: source.fileName,
                        timestamp: ts,
                        seconds: seconds,
                        text: text
                    });
                });
            }
        }

        if (factId) {
            results.push({
                factId: factId,
                factText: facts.find(f => f.id === factId)?.text || "Desconhecido",
                status: status,
                summary: summaryText,
                citations: citations
            });
        }
    }

    return {
      id: Date.now().toString(),
      name: `Relatório #${Math.floor(Date.now() / 1000).toString().slice(-4)}`,
      generatedAt: new Date().toISOString(),
      generalConclusion,
      results
    };

  } catch (error: any) {
    throw new Error(`Erro na análise: ${error.message}`);
  }
};

/**
 * Chat Function
 */
export const chatWithEvidence = async (
  apiKey: string,
  processedData: ProcessedContent[],
  history: ChatMessage[],
  currentMessage: string,
  peopleMap: Record<string, string>,
  fileMetadata: EvidenceFile[]
): Promise<string> => {
   const ai = new GoogleGenAI({ apiKey: apiKey });
   const model = "gemini-2.5-flash"; 

   try {
    const formattedHistory = history.map(h => `${h.role === 'user' ? 'User' : 'AI'}: ${h.text}`).join('\n');

    const evidenceContext = processedData.map(t => {
        const fileData = fileMetadata.find(f => f.id === t.fileId);
        const category = fileData?.category || "OTHER";
        return `
        <document name="${t.fileName}" person="${peopleMap[t.fileId] || 'N/A'}" category="${category}">
        ${t.fullText}
        </document>
    `;
    }).join('\n\n');

    const prompt = `
        BASE DE DADOS:
        ${evidenceContext}

        HISTÓRICO:
        ${formattedHistory}

        PERGUNTA:
        ${currentMessage}

        INSTRUÇÕES DE CITAÇÃO (CRÍTICO):
        Quando a resposta depender de um ficheiro de áudio, tens de usar uma referência clicável.
        Mesmo que identifiques o orador (ex: "Voz 1"), tens de incluir o botão de tempo a seguir.

        FORMATO OBRIGATÓRIO DOS BOTÕES:
        [NomeDoFicheiro.mp3 @ MM:SS]

        EXEMPLOS CORRETOS:
        - "A Voz 1 afirmou que não estava lá [Depoimento.mp3 @ 01:23]."
        - "O arguido negou tudo [Interrogatorio.wav @ 05:40]."

        INSTRUÇÕES GERAIS:
        1. Consulta TUDO antes de responder.
        2. Distingue entre depoimento (category="TESTIMONY") e autos (category="INQUIRY").
        3. Se houver nomes como "Voz 1" ou "Voz 2", usa-os na resposta.

        DETEÇÃO DE PESSOAS:
        [[DETECTED_PEOPLE: Nome | Ficheiro, ...]]
    `;

    const response = await ai.models.generateContent({
        model: model,
        contents: { parts: [{ text: prompt }] },
        config: { temperature: 0.2 }
    });

    return cleanRepetitiveLoops(response.text || "Sem resposta.");
   } catch (error: any) {
     console.error("Chat API Error:", error);
     throw error;
   }
};

import React, { useEffect, useRef, useState } from 'react';
import { EvidenceFile, ProcessedContent } from '../types';
import { Play, Pause, X, Rewind, FastForward, FileText, User, ExternalLink, Search, ChevronUp, ChevronDown, Edit3, Save } from 'lucide-react';

interface EvidenceViewerProps {
  file: EvidenceFile | null;
  processedData: ProcessedContent | undefined;
  initialSeekSeconds: number | null;
  personName?: string;
  onClose: () => void;
  onRenameSpeaker: (fileId: string, oldName: string, newName: string) => void;
}

const EvidenceViewer: React.FC<EvidenceViewerProps> = ({ 
  file, 
  processedData, 
  initialSeekSeconds, 
  personName,
  onClose,
  onRenameSpeaker
}) => {
  const audioRef = useRef<HTMLAudioElement>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [activeSegmentIndex, setActiveSegmentIndex] = useState<number>(-1);

  const [fileUrl, setFileUrl] = useState<string | null>(null);

  // Search State
  const [searchQuery, setSearchQuery] = useState("");
  const [searchResults, setSearchResults] = useState<number[]>([]);
  const [currentResultIndex, setCurrentResultIndex] = useState(0);

  // Speaker Renaming State
  const [showSpeakerTools, setShowSpeakerTools] = useState(false);
  const [detectedSpeakers, setDetectedSpeakers] = useState<string[]>([]);
  const [editingSpeaker, setEditingSpeaker] = useState<string | null>(null);
  const [newSpeakerName, setNewSpeakerName] = useState("");

  useEffect(() => {
    if (file && file.file) {
      const url = URL.createObjectURL(file.file);
      setFileUrl(url);
      return () => {
        URL.revokeObjectURL(url);
      };
    }
    setFileUrl(null);
  }, [file]);

  // Detect Speakers on Load
  useEffect(() => {
      if (processedData) {
          const speakers = new Set<string>();
          processedData.segments.forEach(seg => {
              // Flexible Match: Finds **Speaker** at the start, with or without colon
              const match = seg.text.match(/^\*\*(.*?)\*\*/);
              if (match) {
                  const name = match[1].trim();
                  // Avoid false positives (too long or empty)
                  if (name.length > 0 && name.length < 50) {
                      speakers.add(name);
                  }
              }
          });
          const speakerList = Array.from(speakers).sort();
          setDetectedSpeakers(speakerList);

          // Auto-open tools if speakers are detected (makes feature discoverable)
          if (speakerList.length > 0) {
              setShowSpeakerTools(true);
          }
      }
  }, [processedData]);

  // Search Logic
  useEffect(() => {
      if (!searchQuery.trim() || !processedData) {
          setSearchResults([]);
          return;
      }
      const results = processedData.segments
          .map((seg, idx) => seg.text.toLowerCase().includes(searchQuery.toLowerCase()) ? idx : -1)
          .filter(idx => idx !== -1);

      setSearchResults(results);
      setCurrentResultIndex(0);

      if (results.length > 0) {
          scrollToSegment(results[0]);
      }
  }, [searchQuery, processedData]);

  const handleNextResult = () => {
      if (searchResults.length === 0) return;
      const nextIndex = (currentResultIndex + 1) % searchResults.length;
      setCurrentResultIndex(nextIndex);
      const segIndex = searchResults[nextIndex];
      scrollToSegment(segIndex);
      // Optional: Jump audio too? Yes
      if (processedData) jumpToSegment(processedData.segments[segIndex].seconds);
  };

  const handlePrevResult = () => {
      if (searchResults.length === 0) return;
      const prevIndex = (currentResultIndex - 1 + searchResults.length) % searchResults.length;
      setCurrentResultIndex(prevIndex);
      const segIndex = searchResults[prevIndex];
      scrollToSegment(segIndex);
      if (processedData) jumpToSegment(processedData.segments[segIndex].seconds);
  };

  const handleLoadedMetadata = (e: React.SyntheticEvent<HTMLAudioElement>) => {
      const audio = e.currentTarget;
      setDuration(audio.duration);

      // Seek and Play safely on load
      if (initialSeekSeconds !== null && !isNaN(initialSeekSeconds)) {
          audio.currentTime = Math.max(0, initialSeekSeconds);

          const playPromise = audio.play();
          if (playPromise !== undefined) {
              playPromise
                .then(() => setIsPlaying(true))
                .catch(err => {
                    console.log("Auto-play prevented:", err);
                    setIsPlaying(false);
                });
          }
      }
  };

  const handleTimeUpdate = () => {
    if (audioRef.current) {
      const time = audioRef.current.currentTime;
      setCurrentTime(time);
      if(!Number.isNaN(audioRef.current.duration)) {
          setDuration(audioRef.current.duration);
      }

      if (processedData?.segments) {
        const idx = processedData.segments.findIndex((seg, i) => {
           const nextSeg = processedData.segments[i + 1];
           return time >= seg.seconds && (nextSeg ? time < nextSeg.seconds : true);
        });

        if (idx !== -1 && idx !== activeSegmentIndex) {
            setActiveSegmentIndex(idx);
            scrollToSegment(idx);
        }
      }
    }
  };

  const scrollToSegment = (index: number) => {
      const el = document.getElementById(`seg-${index}`);
      if (el && scrollContainerRef.current) {
          el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
  };

  const jumpToSegment = (seconds: number) => {
      if (audioRef.current) {
          audioRef.current.currentTime = seconds;
          audioRef.current.play()
              .then(() => setIsPlaying(true))
              .catch(console.error);
      }
  };

  const togglePlay = () => {
    if (audioRef.current) {
      if (isPlaying) {
          audioRef.current.pause();
          setIsPlaying(false);
      } else {
          audioRef.current.play().catch(console.error);
          setIsPlaying(true);
      }
    }
  };

  const skip = (amount: number) => {
      if (audioRef.current) {
          audioRef.current.currentTime += amount;
      }
  };

  const formatTime = (time: number) => {
      if (Number.isNaN(time)) return "00:00";
      const m = Math.floor(time / 60);
      const s = Math.floor(time % 60);
      return `${m.toString().padStart(2,'0')}:${s.toString().padStart(2,'0')}`;
  };

  // Helper to highlight text
  const renderHighlightedText = (text: string) => {
      if (!searchQuery.trim()) return text;
      const parts = text.split(new RegExp(`(${searchQuery})`, 'gi'));
      return parts.map((part, i) => 
          part.toLowerCase() === searchQuery.toLowerCase() 
            ? <span key={i} className="bg-yellow-300 dark:bg-yellow-600/50 text-black dark:text-white rounded px-0.5">{part}</span> 
            : part
      );
  };

  const submitRename = (oldName: string) => {
      if(file && newSpeakerName.trim() && newSpeakerName !== oldName) {
          onRenameSpeaker(file.id, oldName, newSpeakerName.trim());
          setEditingSpeaker(null);
          setNewSpeakerName("");

          // Update local state immediately for better UX
          setDetectedSpeakers(prev => prev.map(s => s === oldName ? newSpeakerName.trim() : s));
      }
  };

  if (!file) return null;

  const isAudio = file.type === 'AUDIO';

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
       {/* 80% Screen Modal - Themed */}
       <div className="bg-white dark:bg-slate-900 w-[90%] h-[85%] max-w-6xl rounded-2xl shadow-2xl flex flex-col overflow-hidden border border-gray-200 dark:border-slate-700 animate-in fade-in zoom-in-95 duration-200">

          {/* Header */}
          <div className="h-16 bg-gray-50 dark:bg-slate-950 border-b border-gray-200 dark:border-slate-800 flex items-center justify-between px-6 flex-shrink-0">
             <div className="flex items-center gap-4">
                 <div className={`p-2 rounded-lg ${isAudio ? 'bg-blue-100 text-blue-600 dark:bg-primary-900/30 dark:text-primary-400' : 'bg-orange-100 text-orange-600 dark:bg-orange-900/30 dark:text-orange-400'}`}>
                     {isAudio ? <Play size={20} /> : <FileText size={20} />}
                 </div>
                 <div>
                     <h2 className="text-lg font-bold text-gray-900 dark:text-white truncate max-w-md">{file.name}</h2>
                     {personName && (
                         <div className="flex items-center gap-1.5 text-xs text-gray-500 dark:text-slate-400">
                             <User size={12} /> {personName}
                         </div>
                     )}
                 </div>
             </div>

             <div className="flex items-center gap-2">
                 {fileUrl && (
                     <a 
                         href={fileUrl}
