                    <HelpCircle size={16} />
                    <span className="text-[8px]">Manual</span>
                </button>

                {/* PROJECT ACTIONS */}
                <div className="flex flex-col gap-1 items-center pb-2 border-b border-gray-200 dark:border-slate-800 w-full">
