  const [exportModal, setExportModal] = useState<{ isOpen: boolean, messageId?: string }>({ isOpen: false });
  const [showQuotaModal, setShowQuotaModal] = useState(false);
  const [librarySearch, setLibrarySearch] = useState("");

  useEffect(() => {
    if (isDarkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [isDarkMode]);

  useEffect(() => { setIsRenamingReport(false); setTempReportName(""); }, [selectedReportId]);

  const isQuotaError = (error: any): boolean => {
      const msg = error?.message?.toLowerCase() || "";
      return msg.includes('429') || msg.includes('quota') || msg.includes('resource exhausted') || msg.includes('too many requests');
  };

  const getFileType = (file: File): EvidenceType => {
      if (file.type.startsWith('audio/')) return 'AUDIO';
      if (file.type === 'application/pdf') return 'PDF';
      if (file.type.startsWith('image/')) return 'IMAGE';
      if (file.type.startsWith('text/')) return 'TEXT';
      return 'OTHER';
  };

  const peopleMap = React.useMemo(() => {
      const map: Record<string, string> = {};
      evidenceFiles.forEach(f => {
          if (f.personId) {
              const p = project.people.find(person => person.id === f.personId);
              if (p) map[f.id] = p.name;
          }
      });
      return map;
  }, [evidenceFiles, project.people]);

  const toggleFolder = (folderKey: string) => setExpandedFolders(prev => ({ ...prev, [folderKey]: !prev[folderKey] }));

  const handleOpenOriginal = (fileId: string) => {
      const file = evidenceFiles.find(f => f.id === fileId);
      if (file && file.file) window.open(URL.createObjectURL(file.file), '_blank');
      else alert("Ficheiro original não disponível (Virtual). Arraste o original para re-hidratar.");
  };

  const renderTextWithInlineCitations = (text: string) => {
      const parts = text.split(/(\[.*?\])/g);
      return (<span>{parts.map((part, i) => {
          const matchNameTime = part.match(/^\[(.*?)\s*@\s*(.*?)\]$/); 
          if (matchNameTime) {
              const fileRef = matchNameTime[1];
              const timePart = matchNameTime[2];
              const file = evidenceFiles.find(f => f.name.toLowerCase().includes(fileRef.toLowerCase()) || fileRef.toLowerCase().includes(f.name.toLowerCase()));
              if (file && !file.isVirtual && file.type === 'AUDIO') {
                   return (<button key={i} onClick={(e) => { e.stopPropagation(); setActiveEvidenceId(file.id); setSeekSeconds(parseSecondsSafe(timePart)); }} className="inline-flex items-center gap-0.5 px-1.5 py-0.5 bg-blue-100 dark:bg-primary-900/40 text-blue-700 dark:text-primary-300 rounded text-[10px] font-mono hover:bg-blue-200 dark:hover:bg-primary-900/60 transition-colors border border-blue-200 dark:border-primary-800 shadow-sm cursor-pointer mx-1"><Play size={8} fill="currentColor"/> {timePart}</button>);
              }
          }
          return <span key={i}>{part}</span>;
      })}</span>);
  };

  const renderMessageContent = (msgText: string) => {
      const lines = msgText.split('\n');
      const renderedElements: React.ReactNode[] = [];
      let currentGroup: { fileName: string, lines: string[] } | null = null;
      lines.forEach((line, i) => {
          const match = line.match(/\[(.*?)\s*@/);
          const fileNameRef = match ? match[1].trim() : null;
          if (fileNameRef) {
              if (currentGroup && currentGroup.fileName.toLowerCase() === fileNameRef.toLowerCase()) currentGroup.lines.push(line);
              else {
                  if (currentGroup) renderedElements.push(<CitationGroup key={`group-${i}`} fileName={currentGroup.fileName} contentLines={currentGroup.lines} evidenceFiles={evidenceFiles} onSeek={(fid, sec) => { setActiveEvidenceId(fid); setSeekSeconds(sec); }} onOpenOriginal={handleOpenOriginal} renderInline={renderTextWithInlineCitations}/>);
                  currentGroup = { fileName: fileNameRef, lines: [line] };
              }
          } else {
              if (currentGroup) {
                  renderedElements.push(<CitationGroup key={`group-${i}`} fileName={currentGroup.fileName} contentLines={currentGroup.lines} evidenceFiles={evidenceFiles} onSeek={(fid, sec) => { setActiveEvidenceId(fid); setSeekSeconds(sec); }} onOpenOriginal={handleOpenOriginal} renderInline={renderTextWithInlineCitations}/>);
                  currentGroup = null;
              }
              if (line.trim()) renderedElements.push(<p key={`text-${i}`} className="mb-2 last:mb-0 leading-relaxed">{renderTextWithInlineCitations(line)}</p>);
          }
      });
      if (currentGroup) renderedElements.push(<CitationGroup key={`group-last`} fileName={currentGroup.fileName} contentLines={currentGroup.lines} evidenceFiles={evidenceFiles} onSeek={(fid, sec) => { setActiveEvidenceId(fid); setSeekSeconds(sec); }} onOpenOriginal={handleOpenOriginal} renderInline={renderTextWithInlineCitations}/>);
      return renderedElements;
  };

  const addFiles = (fileList: FileList | File[], category: EvidenceCategory) => {
      const MAX_SIZE = 90 * 1024 * 1024;
      const API_SOFT_LIMIT = 50 * 1024 * 1024;
      let someTooLarge = false;
      let someExceedsAPI = false;

      setEvidenceFiles(prevFiles => {
          const updatedFiles = [...prevFiles];
          const newFilesToAdd: EvidenceFile[] = [];
          Array.from(fileList).forEach((f: File) => {
              if (f.size > MAX_SIZE) someTooLarge = true;
              else if (f.size > API_SOFT_LIMIT) someExceedsAPI = true;
              const relativePath = (f as any).webkitRelativePath || "";
              let folderName = relativePath ? (relativePath.split('/').slice(-2, -1)[0] || "Raiz") : "Raiz";
              const existingIndex = updatedFiles.findIndex(ev => ev.name === f.name && ev.isVirtual && ev.category === category);
              if (existingIndex !== -1) updatedFiles[existingIndex] = { ...updatedFiles[existingIndex], file: f, isVirtual: false, size: f.size };
              else newFilesToAdd.push({ id: Math.random().toString(36).substr(2, 9), file: f, name: f.name, folder: folderName, type: getFileType(f), category: category, size: f.size });
          });
          return [...updatedFiles, ...newFilesToAdd];
      });

      if (someTooLarge) alert("Aviso: Alguns ficheiros excedem 90MB e foram ignorados.");
      else if (someExceedsAPI) alert("Atenção: Detetou ficheiros acima de 50MB. Embora a App aceite até 90MB, a API da Google pode rejeitar ficheiros superiores a 50MB no método direto. Se o processamento falhar, tente comprimir o ficheiro.");
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, category: EvidenceCategory) => { if (e.target.files && e.target.files.length > 0) addFiles(e.target.files, category); };
  const handleDragOver = (e: React.DragEvent, category: EvidenceCategory) => { e.preventDefault(); setDragOverCategory(category); };
  const handleDragLeave = (e: React.DragEvent) => { e.preventDefault(); setDragOverCategory(null); };
  const handleDrop = (e: React.DragEvent, category: EvidenceCategory) => { e.preventDefault(); setDragOverCategory(null); if (e.dataTransfer.files && e.dataTransfer.files.length > 0) addFiles(e.dataTransfer.files, category); };
  const deleteFolder = (category: EvidenceCategory, folderName: string) => { if(confirm(`Apagar pasta "${folderName}"?`)) setEvidenceFiles(prev => prev.filter(f => !(f.category === category && f.folder === folderName))); };

  const handleLoadProject = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      try {
          const result = await loadFromJSON(file);
          if (result.type === 'project') setProject({ ...initialProjectState, people: result.data.people || [], facts: result.data.facts || [], savedReports: result.data.savedReports || [], chatHistory: result.data.chatHistory || [] });
          else if (result.type === 'database') {
              setProject(prev => ({ ...prev, processedData: result.data.processedData || [] }));
              const restored = result.data.fileManifest.map(m => ({ id: m.id, name: m.name, type: m.type as EvidenceType, category: m.category as EvidenceCategory, folder: m.folder || "Importado", file: null, isVirtual: true }));
              setEvidenceFiles(prev => { const ids = new Set(prev.map(f => f.id)); return [...prev, ...restored.filter(f => !ids.has(f.id))]; });
              alert("Base de Dados carregada. Reidrate os ficheiros arrastando os originais.");
          }
      } catch (err: any) { alert(err.message); }
      e.target.value = '';
  };

  const handleNewProject = () => { if(evidenceFiles.length > 0 && !confirm("Limpar dados?")) return; setProject(initialProjectState); setEvidenceFiles([]); setProcessingQueue([]); };

  const runProcessing = async (scope: { type: 'ALL' | 'CATEGORY' | 'FOLDER' | 'FILE', value?: string }) => {
     if (!apiKey) return alert("Chave API em falta.");
     const unprocessed = evidenceFiles.filter(f => {
         if (f.isVirtual || project.processedData.find(pd => pd.fileId === f.id)) return false;
         if (f.file && f.file.size > 90 * 1024 * 1024) return false;
         if (scope.type === 'ALL') return true;
         if (scope.type === 'CATEGORY') return f.category === scope.value;
         if (scope.type === 'FOLDER' && scope.value) { const [cat, ...rest] = scope.value.split('-'); return f.category === cat && f.folder === rest.join('-'); }
         if (scope.type === 'FILE') return f.id === scope.value;
         return false;
     });
     if (unprocessed.length === 0) return alert("Não há ficheiros novos compatíveis (limite 90MB).");
     abortProcessingRef.current = false;
     for (const file of unprocessed) {
         if (abortProcessingRef.current) { setProcessingQueue([]); break; }
         setProcessingQueue(prev => [...prev, file.id]);
         try {
             const result = await processFile(apiKey, file);
             setProject(prev => ({ ...prev, processedData: [...prev.processedData, result] }));
         } catch (e: any) {
             console.error(e);
             if (isQuotaError(e)) { setShowQuotaModal(true); stopProcessing(); break; }
             else alert(`Erro em ${file.name}: ${e.message}`);
         } finally { setProcessingQueue(prev => prev.filter(id => id !== file.id)); }
     }
  };

  const stopProcessing = () => abortProcessingRef.current = true;

  const handleRenameSpeaker = (fileId: string, oldName: string, newName: string) => {
      const processed = project.processedData.find(pd => pd.fileId === fileId);
      if (!processed) return;
      const newSegments = processed.segments.map(seg => ({ ...seg, text: seg.text.replace(new RegExp(`(^|\\s)(\\*\\*)?${oldName}(\\*\\*)?(:)?`, 'g'), `$1**${newName}:**`) }));
      setProject(prev => ({ ...prev, processedData: prev.processedData.map(pd => pd.fileId === fileId ? { ...pd, segments: newSegments, fullText: newSegments.map(s => `[${s.timestamp}] ${s.text}`).join('\n') } : pd) }));
  };

  const addPeopleFromList = () => { const names = newPersonList.split('\n').map(s => s.trim()).filter(s => s.length > 0); setProject(prev => ({ ...prev, people: [...prev.people, ...names.map(name => ({ id: Math.random().toString(36).substr(2, 9), name, role: 'Testemunha' }))] })); setNewPersonList(""); };
  const handleBatchAddPeople = (peopleData: string[]) => {
      const existing = new Set(project.people.map(p => p.name.toLowerCase().trim()));
      const newPeople: Person[] = [];
      const fileUpdates: { fileId: string, personId: string }[] = [];
      peopleData.forEach(entry => {
          const parts = entry.split('|');
          const name = parts[0].trim();
          const fRef = parts[1]?.trim();
          let pid = "";
          if (name && !existing.has(name.toLowerCase())) { pid = Math.random().toString(36).substr(2, 9); newPeople.push({ id: pid, name, role: 'Detetado' }); existing.add(name.toLowerCase()); }
          else pid = project.people.find(p => p.name.toLowerCase() === name.toLowerCase())?.id || "";
          if (pid && fRef) { const f = evidenceFiles.find(ev => ev.name.toLowerCase().includes(fRef.toLowerCase())); if (f && !f.personId) fileUpdates.push({ fileId: f.id, personId: pid }); }
      });
      if (newPeople.length) setProject(p => ({ ...p, people: [...p.people, ...newPeople] }));
      if (fileUpdates.length) setEvidenceFiles(prev => prev.map(f => { const u = fileUpdates.find(up => up.fileId === f.id); return u ? { ...f, personId: u.personId } : f; }));
  };

  const removePerson = (id: string) => { setProject(p => ({ ...p, people: p.people.filter(per => per.id !== id) })); setEvidenceFiles(prev => prev.map(f => f.personId === id ? { ...f, personId: undefined } : f)); };
  const assignPersonToFile = (fileId: string, personId: string) => setEvidenceFiles(prev => prev.map(f => f.id === fileId ? { ...f, personId: personId || undefined } : f));

  const runAnalysis = async () => {
      if (!apiKey) return alert("Chave API.");
      setIsAnalyzing(true);
      try {
          const report = await analyzeFactsFromEvidence(apiKey, project.processedData, project.facts, peopleMap, evidenceFiles);
          setProject(prev => ({ ...prev, savedReports: [report, ...prev.savedReports] }));
          setSelectedReportId(report.id);
          setCurrentView('analysis');
      } catch (e: any) { if (isQuotaError(e)) setShowQuotaModal(true); else alert(e.message); }
      finally { setIsAnalyzing(false); }
  };

  const deleteReport = (id: string) => { if(confirm("Apagar?")) { setProject(p => ({ ...p, savedReports: p.savedReports.filter(r => r.id !== id) })); if(selectedReportId === id) setSelectedReportId(null); } };
  const handleRenameReport = () => { if(selectedReportId && tempReportName.trim()) setProject(p => ({ ...p, savedReports: p.savedReports.map(r => r.id === selectedReportId ? { ...r, name: tempReportName.trim() } : r) })); setIsRenamingReport(false); };
  const updateReport = (id: string, generalConclusion: string, results: any) => { setProject(p => ({ ...p, savedReports: p.savedReports.map(r => r.id === id ? { ...r, generalConclusion, results } : r) })); setEditingReportId(null); };

  const handleExportChat = async (type: 'SINGLE' | 'FULL') => { await exportChatToZip(project.chatHistory, evidenceFiles, type === 'SINGLE' ? exportModal.messageId : undefined); setExportModal({ isOpen: false }); };

  const [chatInput, setChatInput] = useState("");
  const [isChatting, setIsChatting] = useState(false);
  const handleChat = async () => {
      if (!chatInput.trim() || !apiKey) return;
      const msg: ChatMessage = { id: Date.now().toString(), role: 'user', text: chatInput, timestamp: Date.now() };
      setProject(p => ({ ...p, chatHistory: [...p.chatHistory, msg] }));
      setChatInput(""); setIsChatting(true);
      try {
          const resp = await chatWithEvidence(apiKey, project.processedData, [...project.chatHistory, msg], msg.text, peopleMap, evidenceFiles);
          setProject(p => ({ ...p, chatHistory: [...p.chatHistory, { id: (Date.now()+1).toString(), role: 'model', text: resp, timestamp: Date.now() }] }));
      } catch(e: any) { if (isQuotaError(e)) setShowQuotaModal(true); else alert(`Erro: ${e.message}`); }
      finally { setIsChatting(false); }
  };

  const renderFileCard = (file: EvidenceFile) => {
      const isProcessed = project.processedData.some(pd => pd.fileId === file.id);
      const isProcessing = processingQueue.includes(file.id);
      const isTooLarge = file.file && file.file.size > 90 * 1024 * 1024;
      const exceedsAPI = file.file && file.file.size > 50 * 1024 * 1024;

      return (
         <div key={file.id} className={`bg-white dark:bg-slate-900 border p-2 rounded flex flex-col gap-2 group transition-all mb-1 ${isTooLarge ? 'border-red-500 bg-red-50/10' : exceedsAPI && !isProcessed ? 'border-orange-400 bg-orange-50/10' : file.isVirtual ? 'border-orange-200' : 'border-gray-200 dark:border-slate-800 hover:border-gray-400'}`}>
             <div className="flex items-center justify-between">
                 <div className="flex items-center gap-2 overflow-hidden">
                     <div className={`w-6 h-6 rounded flex items-center justify-center shrink-0 text-[10px] ${file.type === 'AUDIO' ? 'bg-blue-100 text-blue-600' : file.type === 'PDF' ? 'bg-red-100 text-red-600' : 'bg-gray-200'}`}>
                         {file.type === 'AUDIO' ? <FileAudio size={12}/> : <FileText size={12}/>}
                     </div>
                     <div className="overflow-hidden">
                         <div className={`text-xs font-medium truncate w-32 ${isTooLarge ? 'text-red-600' : file.isVirtual ? 'text-orange-500' : 'text-gray-700 dark:text-slate-300'}`} title={file.name}>{file.name}</div>
                         <div className="flex items-center gap-2">
                             {isTooLarge ? (<span className="text-[9px] text-red-600 font-bold uppercase"><AlertTriangle size={8}/> MUITO GRANDE</span>) 
                             : exceedsAPI && !isProcessed ? (<span className="text-[9px] text-orange-500 font-bold uppercase"><AlertTriangle size={8}/> RISCO DE ERRO (+50MB)</span>)
                             : file.isVirtual ? (<span className="text-[9px] text-orange-500 font-bold uppercase"><AlertTriangle size={8}/> EM FALTA</span>) 
                             : (<div className={`text-[9px] font-mono uppercase ${isProcessed ? 'text-green-600' : 'text-gray-500'}`}>{isProcessed ? 'PRONTO' : 'PENDENTE'}</div>)}
                         </div>
                     </div>
                 </div>
                 <div className="flex items-center gap-2">
                     {!isProcessed && !isProcessing && !file.isVirtual && !isTooLarge && (<button onClick={(e) => { e.stopPropagation(); runProcessing({ type: 'FILE', value: file.id }); }} className="p-1.5 bg-blue-50 text-blue-600 rounded hover:bg-blue-100"><Play size={10} fill="currentColor" /></button>)}
                     <button onClick={() => setEvidenceFiles(prev => prev.filter(f => f.id !== file.id))} className="text-gray-400 hover:text-red-500"><Trash2 size={12} /></button>
                 </div>
             </div>
             {!isTooLarge && file.category !== 'OTHER' && (<select className="bg-gray-50 dark:bg-slate-900 border border-gray-200 dark:border-slate-800 rounded text-[10px] text-gray-600 py-1" value={file.personId || ""} onChange={(e) => assignPersonToFile(file.id, e.target.value)}><option value="">-- Pessoa --</option>{project.people.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select>)}
             {isProcessing && <div className="text-[10px] text-blue-500 flex items-center gap-1"><Loader2 size={10} className="animate-spin" /> Processando...</div>}
         </div>
      );
  };

  const renderUploadSection = (title: string, category: EvidenceCategory, icon: React.ReactNode, description: string) => {
      const files = evidenceFiles.filter(f => f.category === category);
      const unprocessed = files.filter(f => !project.processedData.find(pd => pd.fileId === f.id) && !(f.file && f.file.size > 90 * 1024 * 1024)).length;
      const folders: Record<string, EvidenceFile[]> = {};
      files.forEach(f => { const k = f.folder || 'Raiz'; if(!folders[k]) folders[k] = []; folders[k].push(f); });
      return (
          <div className={`bg-white dark:bg-slate-900 p-5 rounded-2xl border flex flex-col shadow-sm relative ${dragOverCategory === category ? 'border-primary-500 bg-blue-50 scale-[1.02] z-10' : 'border-gray-200 dark:border-slate-800'}`} onDragOver={(e) => handleDragOver(e, category)} onDragLeave={handleDragLeave} onDrop={(e) => handleDrop(e, category)}>
              <div className="mb-4"><h3 className="text-lg font-bold text-gray-900 dark:text-white flex items-center gap-2 mb-1">{icon} {title}</h3><p className="text-xs text-gray-500">{description}</p></div>
              <div className="flex gap-2 mb-4"><label className="flex-1 px-3 py-2 bg-gray-100 hover:bg-gray-200 rounded-lg text-xs font-bold cursor-pointer flex items-center justify-center gap-2"><FolderOpen size={14}/> Pastas<input type="file" multiple webkitdirectory="" directory="" onChange={(e) => handleFileUpload(e, category)} className="hidden"/></label></div>
              <div className="flex-1 bg-gray-50 dark:bg-slate-925 rounded-xl border p-2 overflow-y-auto max-h-[400px] mb-4 space-y-2">
                  {Object.entries(folders).map(([name, fArr]) => {
                      const k = `${category}-${name}`;
                      return (
                          <div key={k} className="border border-gray-200 dark:border-slate-800 rounded-lg bg-white dark:bg-slate-900/50 overflow-hidden">
                              <div className="p-2 flex items-center justify-between hover:bg-gray-50 cursor-pointer" onClick={() => toggleFolder(k)}><div className="flex items-center gap-2">{expandedFolders[k] ? <ChevronDown size={14}/> : <ChevronRight size={14}/>}<FolderOpen size={14} className="text-primary-500"/><span className="text-xs font-bold truncate max-w-[100px]">{name}</span><span className="text-[10px] text-gray-500">({fArr.length})</span></div><div className="flex gap-1"><button onClick={(e) => { e.stopPropagation(); deleteFolder(category, name); }} className="p-1 hover:text-red-500"><Trash2 size={10}/></button></div></div>
                              {expandedFolders[k] && <div className="p-2 bg-gray-50 dark:bg-slate-950/50 border-t">{fArr.map(renderFileCard)}</div>}
                          </div>
                      );
                  })}
              </div>
              {files.length > 0 && (<button onClick={() => runProcessing({ type: 'CATEGORY', value: category })} disabled={unprocessed === 0 || processingQueue.length > 0} className="w-full py-2 bg-primary-600 text-white rounded-lg text-xs font-bold disabled:bg-gray-300 flex items-center justify-center gap-2">{processingQueue.length > 0 ? <Loader2 size={12} className="animate-spin"/> : <Layers size={12}/>}Processar ({unprocessed})</button>)}
          </div>
      );
  };

  if (currentView === 'landing') return (
      <div className="h-full flex flex-col items-center justify-center p-8 bg-gray-50 dark:bg-slate-950">
          <div className="max-w-4xl w-full text-center space-y-8 animate-in fade-in zoom-in duration-500 flex flex-col items-center">
              <div className="w-20 h-20 bg-primary-600 rounded-3xl flex items-center justify-center shadow-2xl mb-2"><Database size={40} className="text-white"/></div>
              <div><h1 className="text-4xl font-bold text-gray-900 dark:text-white mb-2">Veritas V2.2</h1><p className="text-gray-500">Sistema Forense (Aumentado p/ 90MB)</p></div>
              <div className="flex gap-12 py-4 border-y border-gray-200 w-full justify-center max-w-lg">
                  <div className="flex flex-col items-center"><span className="text-3xl font-bold text-gray-900 dark:text-white">{evidenceFiles.length}</span><span className="text-xs uppercase">Ficheiros</span></div>
                  <div className="flex flex-col items-center"><span className="text-3xl font-bold text-gray-900 dark:text-white">{project.people.length}</span><span className="text-xs uppercase">Pessoas</span></div>
              </div>
              <div className="grid grid-cols-2 gap-4 mt-8 w-full max-w-2xl">
                  <label className="p-5 bg-white dark:bg-slate-900 hover:bg-gray-50 border rounded-2xl flex items-center gap-4 cursor-pointer shadow-sm"><FileText size={20}/><div className="text-left"><h3 className="font-bold text-sm">Projeto</h3><p className="text-[10px]">.json</p></div><input type="file" accept=".json" onChange={handleLoadProject} className="hidden"/></label>
                  <label className="p-5 bg-white dark:bg-slate-900 hover:bg-gray-50 border rounded-2xl flex items-center gap-4 cursor-pointer shadow-sm"><Database size={20}/><div className="text-left"><h3 className="font-bold text-sm">Base Dados</h3><p className="text-[10px]">.json</p></div><input type="file" accept=".json" onChange={handleLoadProject} className="hidden"/></label>
                  <button onClick={() => setCurrentView('setup')} className="col-span-2 p-4 bg-primary-600 hover:bg-primary-500 text-white rounded-2xl font-bold flex items-center justify-center gap-2 mt-4">INICIAR<ChevronRight size={20}/></button>
              </div>
          </div>
      </div>
  );

  return (
    <div className="flex h-screen bg-gray-50 dark:bg-slate-950 text-gray-900 dark:text-slate-200 overflow-hidden">
        <aside className="w-20 bg-white dark:bg-slate-900 border-r flex flex-col items-center py-6 gap-6 z-20 shrink-0">
            <div onClick={() => setCurrentView('landing')} className="w-10 h-10 rounded-xl bg-primary-600 flex items-center justify-center font-bold text-white cursor-pointer">V2</div>
            <nav className="flex flex-col gap-4 w-full px-2">
                {[{id:'setup',icon:LayoutGrid},{id:'people',icon:Users},{id:'library',icon:Library},{id:'analysis',icon:FileText},{id:'chat',icon:MessageSquare}].map(item => (
                    <button key={item.id} onClick={() => setCurrentView(item.id as View)} className={`p-3 rounded-xl flex flex-col items-center transition-all ${currentView === item.id ? 'bg-primary-600 text-white' : 'text-gray-400 hover:bg-gray-100'}`}><item.icon size={20}/></button>
                ))}
            </nav>
            <div className="mt-auto flex flex-col gap-2 w-full px-2 pt-4 border-t">
                <button onClick={() => setIsDarkMode(!isDarkMode)} className="p-2 text-gray-400 hover:text-primary-600 flex flex-col items-center">{isDarkMode ? <Sun size={16}/> : <Moon size={16}/>}</button>
                <button onClick={generateDocumentation} className="p-2 text-gray-400 hover:text-purple-600 flex flex-col items-center"><HelpCircle size={16}/></button>
