        <main className="flex-1 flex flex-col overflow-hidden">
            <header className="h-16 border-b bg-white dark:bg-slate-950/50 backdrop-blur flex items-center px-8 justify-between shrink-0 z-10">
                <h1 className="text-lg font-bold">{currentView.toUpperCase()}</h1>
                <div className="flex items-center gap-4">
                     {currentView === 'setup' && evidenceFiles.filter(f => !f.isVirtual && !project.processedData.find(pd => pd.fileId === f.id)).length > 0 && (
                         processingQueue.length > 0 
                         ? <button onClick={stopProcessing} className="px-4 py-2 bg-red-100 text-red-600 text-xs font-bold rounded-lg"><StopCircle size={14} className="animate-pulse inline mr-2"/>Parar</button>
                         : <button onClick={() => runProcessing({ type: 'ALL' })} className="px-4 py-2 bg-emerald-600 text-white text-xs font-bold rounded-lg">Processar Tudo</button>
                     )}
                </div>
            </header>

            <div className="flex-1 overflow-y-auto p-8">
                {currentView === 'setup' && (
                    <div className="max-w-7xl mx-auto space-y-8">
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                            {renderUploadSection("Depoimentos", 'TESTIMONY', <Mic/>, "Áudios (Max 90MB).")}
                            {renderUploadSection("Autos", 'INQUIRY', <Gavel/>, "PDFs.")}
                            {renderUploadSection("Outros", 'OTHER', <Paperclip/>, "Anexos.")}
                        </div>
                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 border-t pt-8">
                            <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl border shadow-sm">
                                <h3 className="font-bold mb-4 flex items-center gap-2"><CheckCircle2 className="text-primary-500"/> Factos a Provar</h3>
                                <div className="space-y-3 max-h-[300px] overflow-y-auto pr-2">
                                    {project.facts.map((fact, idx) => (
                                        <div key={fact.id} className="flex gap-2 group">
                                            <textarea value={fact.text} onChange={(e) => setProject(p => ({ ...p, facts: p.facts.map(f => f.id === fact.id ? { ...f, text: e.target.value } : f) }))} className="w-full bg-gray-50 dark:bg-slate-950 border rounded-lg p-3 text-sm focus:border-primary-500 outline-none resize-none h-20"/>
                                            <button onClick={() => setProject(p => ({ ...p, facts: p.facts.filter(f => f.id !== fact.id) }))} className="p-2 text-gray-400 hover:text-red-500"><Trash2 size={16}/></button>
                                        </div>
                                    ))}
                                </div>
                                <button onClick={() => setProject(p => ({ ...p, facts: [...p.facts, { id: Math.random().toString(36), text: "" }] }))} className="mt-4 text-xs text-primary-600 font-bold uppercase"><Plus size={14} className="inline mr-1"/>Adicionar Facto</button>
                            </div>
                            <div className="flex flex-col justify-center items-center p-8 border-2 border-dashed rounded-2xl">
                                <PlayCircle size={48} className="text-primary-600 mb-4"/><h3 className="text-xl font-bold mb-2">Análise Cruzada</h3>
                                <p className="text-sm text-gray-500 text-center mb-6">Processa factos cruzando dados (Limite 90MB).</p>
                                <button onClick={runAnalysis} disabled={isAnalyzing} className="px-8 py-3 bg-primary-600 text-white rounded-full font-bold shadow-lg shadow-primary-900/20">{isAnalyzing ? <Loader2 className="animate-spin"/> : "Gerar Relatório"}</button>
                            </div>
                        </div>
                    </div>
                )}
                {/* Outras Views... */}
            </div>
        </main>

        {activeEvidenceId && (
            <EvidenceViewer 
                file={evidenceFiles.find(f => f.id === activeEvidenceId) || null}
                processedData={project.processedData.find(pd => pd.fileId === activeEvidenceId)}
                initialSeekSeconds={seekSeconds}
                onClose={() => { setActiveEvidenceId(null); setSeekSeconds(null); }}
                onRenameSpeaker={handleRenameSpeaker}
            />
        )}

        {showQuotaModal && (
            <div className="fixed inset-0 z-[60] bg-black/90 flex items-center justify-center p-4">
                 <div className="bg-white dark:bg-slate-900 p-8 rounded-2xl max-w-sm text-center shadow-2xl">
                     <AlertTriangle size={32} className="mx-auto mb-4 text-red-500"/>
                     <h3 className="text-xl font-bold mb-2">Limite de Quota</h3>
                     <p className="text-sm text-gray-600 mb-6">Aguarde alguns instantes antes de tentar novamente.</p>
                     <button onClick={() => setShowQuotaModal(false)} className="w-full py-2.5 bg-red-600 text-white rounded-xl font-bold">Entendido</button>
                 </div>
            </div>
        )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { 
  Upload, FileText, MessageSquare, PlayCircle, Save, FolderOpen, Plus, Trash2,
  CheckCircle2, AlertCircle, Loader2, FileAudio, BrainCircuit, Database, 
  X, Key, Users, File, FileImage, LayoutGrid, Paperclip, Mic, Gavel, Edit2, Check,
  ChevronDown, ChevronRight, StopCircle, Play, Layers, ArrowUp, ArrowDown, LogOut, ExternalLink, AlertTriangle, Sun, Moon, Pencil, ChevronUp, UserPlus, Download, ZapOff, Library, Headphones, Music, HelpCircle
} from 'lucide-react';
import { EvidenceFile, Fact, ProjectState, ChatMessage, ProcessedContent, Person, EvidenceType, Citation, EvidenceCategory, AnalysisReport, SerializedProject, SerializedDatabase } from './types';
import { processFile, analyzeFactsFromEvidence, chatWithEvidence, sanitizeTranscript, parseSecondsSafe } from './services/geminiService';
import { exportToWord, saveProjectFile, saveDatabaseFile, loadFromJSON, exportChatToZip } from './utils/exportService';
import { generateDocumentation } from './utils/documentationGenerator';
import EvidenceViewer from './components/EvidenceViewer';

// --- INITIAL STATE ---
const initialProjectState: ProjectState = {
  people: [],
  facts: [],
  processedData: [], 
  savedReports: [],
  chatHistory: [],
  lastModified: Date.now(),
};

type View = 'landing' | 'setup' | 'people' | 'analysis' | 'chat' | 'library';

// GROUPED CITATION COMPONENT (Audio Bar Style)
const CitationGroup: React.FC<{ 
    fileName: string;
    contentLines: string[];
    evidenceFiles: EvidenceFile[]; 
    onSeek: (fileId: string, seconds: number) => void; 
    onOpenOriginal: (fileId: string) => void;
    renderInline: (text: string) => React.ReactNode;
}> = ({ fileName, contentLines, evidenceFiles, onSeek, onOpenOriginal, renderInline }) => {

    const evidence = evidenceFiles.find(f => f.name.toLowerCase().includes(fileName.toLowerCase()) || fileName.toLowerCase().includes(f.name.toLowerCase()));
    const allTimestamps: { label: string, seconds: number }[] = [];
    contentLines.forEach(line => {
        const regex = /\[(?:.*?@\s*)?(\d{1,2}:\d{2}(?::\d{2})?)(?:\])?/g; 
        let match;
        while ((match = regex.exec(line)) !== null) {
            allTimestamps.push({ label: match[1], seconds: parseSecondsSafe(match[1]) });
        }
    });
    const uniqueTimestamps = allTimestamps.filter((v, i, a) => a.findIndex(t => t.label === v.label) === i).sort((a,b) => a.seconds - b.seconds);

    return (
        <div className="my-3 bg-white dark:bg-slate-900/50 rounded-lg border border-gray-200 dark:border-slate-800 overflow-hidden shadow-sm transition-all group text-left">
            <div className="px-3 py-2 bg-blue-50 dark:bg-primary-900/20 border-b border-gray-100 dark:border-slate-800 flex items-center justify-between">
                <div className="flex items-center gap-2">
                    <FileAudio size={14} className="text-primary-600 dark:text-primary-400" />
                    <span className="text-xs font-bold text-primary-700 dark:text-primary-300 uppercase truncate max-w-[200px]" title={fileName}>{fileName}</span>
                </div>
                 {evidence && !evidence.isVirtual && (
                     <button 
                        onClick={(e) => { e.stopPropagation(); onOpenOriginal(evidence.id); }}
                        className="flex items-center gap-1 px-2 py-0.5 bg-white dark:bg-slate-800 border border-gray-200 dark:border-slate-700 rounded text-[10px] text-gray-500 dark:text-slate-400 hover:text-primary-600 dark:hover:text-primary-400 transition-colors"
                     >
                         <ExternalLink size={10} /> Abrir Original
                     </button>
                 )}
            </div>

            <div className="p-4 text-sm text-gray-700 dark:text-slate-300 leading-relaxed space-y-2">
                {contentLines.map((line, i) => (
                    <div key={i}>{renderInline(line)}</div>
                ))}
            </div>

            {evidence && uniqueTimestamps.length > 0 && evidence.type === 'AUDIO' && (
                <div className="px-3 py-2 bg-gray-50 dark:bg-slate-950 border-t border-gray-200 dark:border-slate-800 flex flex-wrap gap-2 items-center">
                    <span className="text-[10px] font-bold text-gray-400 dark:text-slate-600 uppercase mr-2">Ouvir em:</span>
                    {uniqueTimestamps.map((ts, idx) => (
                         <button 
                            key={idx}
                            onClick={(e) => { e.stopPropagation(); onSeek(evidence.id, ts.seconds); }}
                            className="flex items-center gap-1 px-2 py-1 bg-blue-100 dark:bg-primary-900/30 text-blue-700 dark:text-primary-300 rounded-md text-[10px] font-mono hover:bg-blue-200 dark:hover:bg-primary-900/50 transition-colors border border-blue-200 dark:border-primary-800/50"
                        >
                            <Play size={8} fill="currentColor"/> {ts.label}
                        </button>
                    ))}
                </div>
            )}
        </div>
    );
};

const App: React.FC = () => {
  const [apiKey, setApiKey] = useState<string>(localStorage.getItem("veritas_api_key") || "");
  const [tempApiKey, setTempApiKey] = useState("");
  const [isDarkMode, setIsDarkMode] = useState<boolean>(true);
  const [currentView, setCurrentView] = useState<View>('landing');
  const [evidenceFiles, setEvidenceFiles] = useState<EvidenceFile[]>([]); 
  const [project, setProject] = useState<ProjectState>(initialProjectState);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [processingQueue, setProcessingQueue] = useState<string[]>([]);
  const abortProcessingRef = useRef<boolean>(false);
  const [activeEvidenceId, setActiveEvidenceId] = useState<string | null>(null);
  const [seekSeconds, setSeekSeconds] = useState<number | null>(null);
  const [isManualImportOpen, setIsManualImportOpen] = useState(false);
  const [manualText, setManualText] = useState("");
  const [manualName, setManualName] = useState("");
  const [manualCategory, setManualCategory] = useState<EvidenceCategory>('TESTIMONY');
  const [newPersonList, setNewPersonList] = useState("");
  const [editingReportId, setEditingReportId] = useState<string | null>(null);
  const [selectedReportId, setSelectedReportId] = useState<string | null>(null);
  const [isRenamingReport, setIsRenamingReport] = useState(false);
  const [tempReportName, setTempReportName] = useState("");
  const [expandedFolders, setExpandedFolders] = useState<Record<string, boolean>>({});
  const [dragOverCategory, setDragOverCategory] = useState<EvidenceCategory | null>(null);
  const [exportModal, setExportModal] = useState<{ isOpen: boolean, messageId?: string }>({ isOpen: false });
  const [showQuotaModal, setShowQuotaModal] = useState(false);
  const [librarySearch, setLibrarySearch] = useState("");

  useEffect(() => {
    if (isDarkMode) document.documentElement.classList.add('dark');
    else document.documentElement.classList.remove('dark');
  }, [isDarkMode]);

  const isQuotaError = (error: any): boolean => {
      const msg = error?.message?.toLowerCase() || "";
      return msg.includes('429') || msg.includes('quota') || msg.includes('resource exhausted') || msg.includes('too many requests');
  };

  const getFileType = (file: File): EvidenceType => {
      if (file.type.startsWith('audio/')) return 'AUDIO';
      if (file.type === 'application/pdf') return 'PDF';
      if (file.type.startsWith('image/')) return 'IMAGE';
      if (file.type.startsWith('text/')) return 'TEXT';
      return 'OTHER';
  };

  const peopleMap = React.useMemo(() => {
      const map: Record<string, string> = {};
      evidenceFiles.forEach(f => {
          if (f.personId) {
              const p = project.people.find(person => person.id === f.personId);
              if (p) map[f.id] = p.name;
          }
      });
      return map;
  }, [evidenceFiles, project.people]);

  const toggleFolder = (folderKey: string) => setExpandedFolders(prev => ({ ...prev, [folderKey]: !prev[folderKey] }));

  const handleOpenOriginal = (fileId: string) => {
      const file = evidenceFiles.find(f => f.id === fileId);
      if (file && file.file) window.open(URL.createObjectURL(file.file), '_blank');
      else alert("Ficheiro original não disponível (Virtual). Arraste o original para reativar.");
  };

  const renderTextWithInlineCitations = (text: string) => {
      const parts = text.split(/(\[.*?\])/g);
      return (
        <span>
            {parts.map((part, i) => {
                const matchNameTime = part.match(/^\[(.*?)\s*@\s*(.*?)\]$/); 
                if (matchNameTime) {
                    const fileRef = matchNameTime[1];
                    const timePart = matchNameTime[2];
                    const file = evidenceFiles.find(f => f.name.toLowerCase().includes(fileRef.toLowerCase()) || fileRef.toLowerCase().includes(f.name.toLowerCase()));
                    if (file && !file.isVirtual && file.type === 'AUDIO') {
                         return (
                            <button key={i} onClick={(e) => { e.stopPropagation(); setActiveEvidenceId(file.id); setSeekSeconds(parseSecondsSafe(timePart)); }} className="inline-flex items-center gap-0.5 px-1.5 py-0.5 bg-blue-100 dark:bg-primary-900/40 text-blue-700 dark:text-primary-300 rounded text-[10px] font-mono hover:bg-blue-200 dark:hover:bg-primary-900/60 transition-colors border border-blue-200 dark:border-primary-800 shadow-sm mx-1">
                                <Play size={8} fill="currentColor"/> {timePart}
                            </button>
                        );
                    }
                }
                return <span key={i}>{part}</span>;
            })}
        </span>
      );
  };

  const renderMessageContent = (msgText: string) => {
      const lines = msgText.split('\n');
      const renderedElements: React.ReactNode[] = [];
      let currentGroup: { fileName: string, lines: string[] } | null = null;
      lines.forEach((line, i) => {
          const match = line.match(/\[(.*?)\s*@/);
          const fileNameRef = match ? match[1].trim() : null;
          if (fileNameRef) {
              if (currentGroup && currentGroup.fileName.toLowerCase() === fileNameRef.toLowerCase()) currentGroup.lines.push(line);
              else {
                  if (currentGroup) renderedElements.push(<CitationGroup key={`group-${i}`} fileName={currentGroup.fileName} contentLines={currentGroup.lines} evidenceFiles={evidenceFiles} onSeek={(fid, sec) => { setActiveEvidenceId(fid); setSeekSeconds(sec); }} onOpenOriginal={handleOpenOriginal} renderInline={renderTextWithInlineCitations}/>);
                  currentGroup = { fileName: fileNameRef, lines: [line] };
              }
          } else {
              if (currentGroup) {
                  renderedElements.push(<CitationGroup key={`group-${i}`} fileName={currentGroup.fileName} contentLines={currentGroup.lines} evidenceFiles={evidenceFiles} onSeek={(fid, sec) => { setActiveEvidenceId(fid); setSeekSeconds(sec); }} onOpenOriginal={handleOpenOriginal} renderInline={renderTextWithInlineCitations}/>);
                  currentGroup = null;
              }
              if (line.trim()) renderedElements.push(<p key={`text-${i}`} className="mb-2 last:mb-0 leading-relaxed text-left">{renderTextWithInlineCitations(line)}</p>);
          }
      });
      if (currentGroup) renderedElements.push(<CitationGroup key={`group-last`} fileName={currentGroup.fileName} contentLines={currentGroup.lines} evidenceFiles={evidenceFiles} onSeek={(fid, sec) => { setActiveEvidenceId(fid); setSeekSeconds(sec); }} onOpenOriginal={handleOpenOriginal} renderInline={renderTextWithInlineCitations}/>);
      return renderedElements;
  };

  const addFiles = (fileList: FileList | File[], category: EvidenceCategory) => {
      const MAX_SIZE = 90 * 1024 * 1024;
      const API_SOFT_LIMIT = 50 * 1024 * 1024;
      let someTooLarge = false;
      let someExceedsAPI = false;

      setEvidenceFiles(prevFiles => {
          const updatedFiles = [...prevFiles];
          const newFilesToAdd: EvidenceFile[] = [];
          Array.from(fileList).forEach((f: File) => {
              if (f.size > MAX_SIZE) someTooLarge = true;
              else if (f.size > API_SOFT_LIMIT) someExceedsAPI = true;
              const relativePath = (f as any).webkitRelativePath || "";
              let folderName = relativePath ? (relativePath.split('/').slice(-2, -1)[0] || "Raiz") : "Raiz";
              const existingIndex = updatedFiles.findIndex(ev => ev.name === f.name && ev.isVirtual && ev.category === category);
              if (existingIndex !== -1) updatedFiles[existingIndex] = { ...updatedFiles[existingIndex], file: f, isVirtual: false, size: f.size };
              else newFilesToAdd.push({ id: Math.random().toString(36).substr(2, 9), file: f, name: f.name, folder: folderName, type: getFileType(f), category: category, size: f.size });
          });
          return [...updatedFiles, ...newFilesToAdd];
      });

      if (someTooLarge) alert("Aviso: Alguns ficheiros excedem 90MB e foram ignorados.");
      else if (someExceedsAPI) alert("Atenção: Ficheiros acima de 50MB detetados. A Google pode rejeitar ficheiros superiores a 50MB se o tráfego for elevado. Tente comprimir se o processamento falhar.");
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, category: EvidenceCategory) => { if (e.target.files && e.target.files.length > 0) addFiles(e.target.files, category); };
  const handleDragOver = (e: React.DragEvent, category: EvidenceCategory) => { e.preventDefault(); setDragOverCategory(category); };
  const handleDrop = (e: React.DragEvent, category: EvidenceCategory) => { e.preventDefault(); setDragOverCategory(null); if (e.dataTransfer.files && e.dataTransfer.files.length > 0) addFiles(e.dataTransfer.files, category); };

  const handleLoadProject = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      try {
          const result = await loadFromJSON(file);
          if (result.type === 'project') setProject({ ...initialProjectState, people: result.data.people || [], facts: result.data.facts || [], savedReports: result.data.savedReports || [], chatHistory: result.data.chatHistory || [] });
          else if (result.type === 'database') {
              setProject(prev => ({ ...prev, processedData: result.data.processedData || [] }));
              const restored = result.data.fileManifest.map(m => ({ id: m.id, name: m.name, type: m.type as EvidenceType, category: m.category as EvidenceCategory, folder: m.folder || "Importado", file: null, isVirtual: true }));
              setEvidenceFiles(prev => { const ids = new Set(prev.map(f => f.id)); return [...prev, ...restored.filter(f => !ids.has(f.id))]; });
              alert("Base de Dados carregada.");
          }
      } catch (err: any) { alert(err.message); }
      e.target.value = '';
  };

  const runProcessing = async (scope: { type: 'ALL' | 'CATEGORY' | 'FOLDER' | 'FILE', value?: string }) => {
     if (!apiKey) return alert("Chave API em falta.");
     const unprocessed = evidenceFiles.filter(f => {
         if (f.isVirtual || project.processedData.find(pd => pd.fileId === f.id)) return false;
         if (f.file && f.file.size > 90 * 1024 * 1024) return false;
         if (scope.type === 'ALL') return true;
         if (scope.type === 'CATEGORY') return f.category === scope.value;
         if (scope.type === 'FOLDER' && scope.value) { const [cat, ...rest] = scope.value.split('-'); return f.category === cat && f.folder === rest.join('-'); }
         if (scope.type === 'FILE') return f.id === scope.value;
         return false;
     });
     if (unprocessed.length === 0) return alert("Não há ficheiros novos compatíveis (limite 90MB).");
     abortProcessingRef.current = false;
     for (const file of unprocessed) {
         if (abortProcessingRef.current) { setProcessingQueue([]); break; }
         setProcessingQueue(prev => [...prev, file.id]);
         try {
             const result = await processFile(apiKey, file);
             setProject(prev => ({ ...prev, processedData: [...prev.processedData, result] }));
         } catch (e: any) {
             if (isQuotaError(e)) { setShowQuotaModal(true); stopProcessing(); break; }
             else alert(`Erro em ${file.name}: ${e.message}`);
         } finally { setProcessingQueue(prev => prev.filter(id => id !== file.id)); }
     }
  };

  const stopProcessing = () => abortProcessingRef.current = true;
  const handleRenameSpeaker = (fileId: string, oldName: string, newName: string) => {
      const processed = project.processedData.find(pd => pd.fileId === fileId);
      if (!processed) return;
      const newSegments = processed.segments.map(seg => ({ ...seg, text: seg.text.replace(new RegExp(`(^|\\s)(\\*\\*)?${oldName}(\\*\\*)?(:)?`, 'g'), `$1**${newName}:**`) }));
      setProject(prev => ({ ...prev, processedData: prev.processedData.map(pd => pd.fileId === fileId ? { ...pd, segments: newSegments, fullText: newSegments.map(s => `[${s.timestamp}] ${s.text}`).join('\n') } : pd) }));
  };

  const runAnalysis = async () => {
      if (!apiKey) return alert("Chave API.");
      setIsAnalyzing(true);
      try {
          const report = await analyzeFactsFromEvidence(apiKey, project.processedData, project.facts, peopleMap, evidenceFiles);
          setProject(prev => ({ ...prev, savedReports: [report, ...prev.savedReports] }));
          setSelectedReportId(report.id);
          setCurrentView('analysis');
      } catch (e: any) { if (isQuotaError(e)) setShowQuotaModal(true); else alert(e.message); }
      finally { setIsAnalyzing(false); }
  };

  const handleChat = async () => {
      if (!chatInput.trim() || !apiKey) return;
      const msg: ChatMessage = { id: Date.now().toString(), role: 'user', text: chatInput, timestamp: Date.now() };
      setProject(p => ({ ...p, chatHistory: [...p.chatHistory, msg] }));
      setChatInput(""); setIsChatting(true);
      try {
          const resp = await chatWithEvidence(apiKey, project.processedData, [...project.chatHistory, msg], msg.text, peopleMap, evidenceFiles);
          setProject(p => ({ ...p, chatHistory: [...p.chatHistory, { id: (Date.now()+1).toString(), role: 'model', text: resp, timestamp: Date.now() }] }));
      } catch(e: any) { if (isQuotaError(e)) setShowQuotaModal(true); else alert(`Erro: ${e.message}`); }
      finally { setIsChatting(false); }
  };

  const renderFileCard = (file: EvidenceFile) => {
      const isProcessed = project.processedData.some(pd => pd.fileId === file.id);
      const isProcessing = processingQueue.includes(file.id);
      const isTooLarge = file.file && file.file.size > 90 * 1024 * 1024;
      const exceedsAPI = file.file && file.file.size > 50 * 1024 * 1024;

      return (
         <div key={file.id} className={`bg-white dark:bg-slate-900 border p-2 rounded flex flex-col gap-2 group transition-all mb-1 ${isTooLarge ? 'border-red-500 bg-red-50/10' : exceedsAPI && !isProcessed ? 'border-orange-400 bg-orange-50/10' : file.isVirtual ? 'border-orange-200' : 'border-gray-200 dark:border-slate-800'}`}>
             <div className="flex items-center justify-between">
                 <div className="flex items-center gap-2 overflow-hidden">
                     <div className={`w-6 h-6 rounded flex items-center justify-center shrink-0 text-[10px] ${file.type === 'AUDIO' ? 'bg-blue-100 text-blue-600' : 'bg-red-100 text-red-600'}`}>
                         {file.type === 'AUDIO' ? <FileAudio size={12}/> : <FileText size={12}/>}
                     </div>
                     <div className="overflow-hidden">
                         <div className="text-xs font-medium truncate w-32 dark:text-slate-300" title={file.name}>{file.name}</div>
                         <div className="flex items-center gap-2">
                             {isTooLarge ? <span className="text-[9px] text-red-600 font-bold uppercase">MUITO GRANDE</span> 
                             : exceedsAPI && !isProcessed ? <span className="text-[9px] text-orange-500 font-bold uppercase">RISCO (+50MB)</span>
                             : file.isVirtual ? <span className="text-[9px] text-orange-500 font-bold uppercase">EM FALTA</span> 
                             : <div className={`text-[9px] font-mono uppercase ${isProcessed ? 'text-green-600' : 'text-gray-500'}`}>{isProcessed ? 'PRONTO' : 'PENDENTE'}</div>}
                         </div>
                     </div>
