// Fix: Removed apiKey parameter and initialized GoogleGenAI with process.env.API_KEY
export const chatWithEvidence = async (
  processedData: ProcessedContent[],
  history: ChatMessage[],
  currentMessage: string,
  peopleMap: Record<string, string>,
  fileMetadata: EvidenceFile[]
): Promise<string> => {
   const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
   const model = "gemini-3-flash-preview"; 
   try {
    const evidenceContext = processedData.map(t => `<doc name="${t.fileName}">${t.fullText}</doc>`).join('\n');
    const response = await ai.models.generateContent({
        model: model,
        contents: { parts: [{ text: `EVIDÊNCIAS:\n${evidenceContext}\n\nPERGUNTA: ${currentMessage}\n\nCITAÇÃO: [Ficheiro @ MM:SS]` }] },
        config: { temperature: 0.2 }
    });
    return cleanRepetitiveLoops(response.text || "Sem resposta.");
   } catch (error: any) { throw error; }
};

