                             )}
                             {!isPlaying && <Play size={48} className="text-gray-300 dark:text-slate-700" />}
                         </div>

                         <div className="space-y-4">
                             <div className="flex justify-between text-xs font-mono text-gray-500 dark:text-slate-400">
